  SELECT
    item_nbr AS item_key2,
    store_nbr
    -- Actual
    ,

    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12318)THEN c.wkly_qty END ),0) AS qty_wk23_18,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12319)THEN c.wkly_qty END ),0) AS qty_wk23_19,

    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12317)THEN c.FRI_QTY END ),0) AS qty_2605,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12318)THEN c.SAT_QTY END ),0) AS qty_2705,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12318)THEN c.SUN_QTY END ),0) AS qty_2805,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12318)THEN c.MON_QTY END ),0) AS qty_2905,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12318)THEN c.THU_QTY END ),0) AS qty_3005,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12318)THEN c.WED_QTY END ),0) AS qty_3105,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12318)THEN c.TUE_QTY END ),0) AS qty_0106,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12318)THEN c.FRI_QTY END ),0) AS qty_0206,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12319)THEN c.SAT_QTY END ),0) AS qty_0306,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12319)THEN c.SUN_QTY END ),0) AS qty_0406,
    COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12319)THEN c.MON_QTY END ),0) AS qty_0506,

    --precio venta

    --COALESCE(SUM(CASE WHEN(c.wm_yr_wk =12318)THEN c.wkly_qty*c.SELL_PRICE END ),0) AS qty_wk22_18_price,

  
  FROM
    wmt-edw-prod.MX_WC_VM.SKU_DLY_POS c -- ventas
  
  GROUP BY
    1,
    2) AS ventas
ON
  (inventario.item_key = ventas.item_key2
    AND inventario.club_nbr = ventas.store_nbr )
ORDER BY
  inventario.Vendor_nbr,
  inventario.Item_nbr